package com.samsixx.pocket2droid;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class RomDeviceStateTest {
 static int checks;static void yes(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 public static void main(String[]args)throws Exception{
  if(args.length>0&&args[0].equals("invalid-key")){RomUpdateTest.Fixture f=new RomUpdateTest.Fixture("invalid-key",false);File meta=new File(f.original.storage.getParentFile(),"profile.json");JSONObject value=new JSONObject(new String(Files.readAllBytes(meta.toPath()),"UTF-8")).put("settingsKey",123);RomUpdateTest.write(meta,value.toString().getBytes("UTF-8"));try{f.repository.getProfile("Old.BIN");throw new AssertionError("Corrupt device identity must not be coerced into a different settings key");}catch(IOException expected){yes(RomUpdateTest.hash(f.original.storage).equals(f.digest),"Corrupt identity rejection preserves installation bytes");}System.out.println("PASS malformed device identity protection");return;}
  if(args.length>0&&args[0].equals("fence")){RomUpdateTest.Fixture f=new RomUpdateTest.Fixture("fence",false);RomProfile p=f.original;RomProfile stale=new RomProfile(p.filename,p.iconId,p.rom,p.storage,p.settings,p.saveState,p.error,"rom-0123456789abcdef0123456789abcdef");try{new StorageLayout(f.repository.root,f.repository.runtime,stale).prepare();throw new AssertionError("A changed device-settings identity must block stale launch preparation");}catch(IOException expected){yes(RomUpdateTest.hash(p.storage).equals(f.digest),"Stale launch rejection preserves saved storage");}System.out.println("PASS device-settings launch fence");return;}
  RomUpdateTest.Fixture f=new RomUpdateTest.Fixture("device",false);File files=new File(f.base,"app-files");files.mkdir();String before=GlesSetup.sha("Old.BIN".getBytes("UTF-8"));File cache=new File(files,"gles/"+before);cache.mkdirs();File packet=new File(cache,"request.bin");RomUpdateTest.write(packet,new byte[]{1,2,3});
  String key=RomDeviceState.prepare(files,f.original);yes(key.matches("rom-[0-9a-f]{32}")&&!key.equals(f.original.settingsKey),"Legacy installation receives stable key");File migrated=new File(files,"gles/"+GlesSetup.sha(key.getBytes("UTF-8")));yes(migrated.isDirectory()&&migrated.list().length==0,"Eligibility migrates without packets");yes(Arrays.equals(Files.readAllBytes(packet.toPath()),new byte[]{1,2,3}),"Original history retained");
  RomProfile stable=new RomProfile("New.BIN",f.original.iconId,f.original.rom,f.original.storage,f.original.settings,f.original.saveState,null,key);yes(RomDeviceState.prepare(files,stable).equals(key),"Repeated update retains key");
  RomProfile fresh=f.repository.importRom(new ByteArrayInputStream("fresh".getBytes("UTF-8")),"Fresh.BIN");yes(!fresh.settingsKey.equals(key)&&fresh.settingsKey.startsWith("rom-"),"Fresh installation has independent history");
  File badFiles=new File(f.base,"bad-private");badFiles.mkdir();RomUpdateTest.write(new File(badFiles,"gles/"+before),new byte[]{1});String save=RomUpdateTest.hash(f.original.storage);try{RomDeviceState.prepare(badFiles,f.original);throw new AssertionError("Invalid history must fail");}catch(IOException expected){checks++;}yes(RomUpdateTest.hash(f.original.storage).equals(save),"Failed identity preparation leaves save intact");System.out.println("PASS ROM graphics identity "+checks+" filesystem assertions");
 }
}
